fn sv(i: i32) -> i32 {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    tab[i & 31]
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2;
    let r: i32 = if w < h { w / 2 - 30 } else { h / 2 - 30 };
    if host::display::state_get(2) == 0 {
        host::display::state_set(2, 1);
        host::display::state_set(0, 1800);
    }
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(1);
    let mut rem: i32 = host::display::state_get(0);
    if down == 1 && prev == 0 { rem = 1800; }
    if rem > 0 { rem = rem - 1; }
    host::display::state_set(0, rem);
    host::display::state_set(1, down);
    let bg: i32 = if rem == 0 && (t / 8) % 2 == 0 { 0x400000 } else { 0x0a0a0a };
    host::display::clear(bg);
    let lit: i32 = (rem * 32 + 1799) / 1800;
    let mut i: i32 = 0;
    while i < 32 {
        let x: i32 = cx + sv(i) * r / 127;
        let y: i32 = cy - sv(i + 8) * r / 127;
        let col: i32 = if i < lit { 0x00d0ff } else { 0x202020 };
        host::display::fill_rect(x - 5, y - 5, 11, 11, col);
        i = i + 1;
    }
    let secs: i32 = (rem + 59) / 60;
    host::display::draw_number(cx - 16, cy - 16, secs, 0xffffff, 4);
    if rem == 0 {
        host::display::draw_string(cx - 44, cy + 30, "TAP TO RESET", 0xff8080, 1);
    }
    host::display::present();
}
